#!/usr/bin/env python3
"""Categorize the changes of a batch's commits. Read-only on the repo."""
import subprocess, sys, re, os, json, collections

REPO = '/home/user/fortress'

def git(*args, binary=False):
    out = subprocess.run(['git', '-C', REPO] + list(args), capture_output=True, check=True).stdout
    return out if binary else out.decode('utf-8', 'replace')

COORD = {
    'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
    'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
    'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md',
}
TESTDIR = re.compile(r'^ProjectFortress/([^/]*(tests?|_tests|test_library|not_passing_yet|long_term_not_working|compiler_regressions|shelltests|test_leaks)[^/]*)/')
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json', '.compile', '.run', '.err', '.stdout', '.stderr', '.diff', '.before', '.after'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.pl', '.rb', '.awk', '.sed', '.bash'}

def category(p):
    if p in COORD:
        return 'COORD'
    if p.startswith('explorations/'):
        base = os.path.basename(p)
        ext = os.path.splitext(base)[1].lower()
        if ext == '.md':
            return 'REC:REPORTS'
        if ext in PROBE:
            return 'REC:PROBES'
        if ext in SCRIPT:
            return 'REC:SCRIPTS'
        if ext in CAPT or '/raw/' in p or '/raw-before/' in p:
            return 'REC:CAPTURES'
        return 'REC:OTHER'
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'):
        return 'CODE:library'
    if TESTDIR.match(p):
        return 'TESTS'
    if p.startswith('ProjectFortress/src/') and p.endswith('.java'):
        return 'CODE:java'
    if p.startswith('ProjectFortress/src/') and p.endswith('.scala'):
        return 'CODE:scala'
    if p.startswith('ProjectFortress/astgen/'):
        return 'CODE:astgen'
    if os.path.basename(p) in ('build.xml',) or p.startswith('bin/') or p.endswith('.properties'):
        return 'CODE:build'
    if p.startswith('Specification/') and p.endswith('.tex'):
        return 'SPEC:tex'
    if p == 'Specification/fortress.pdf':
        return 'SPEC:pdf'
    return 'ELSEWHERE'

def commit_changes(c):
    """Return list of (status, old, new, add, del) for commit c."""
    raw = git('show', '--raw', '-M', '-z', '--format=', '--no-abbrev', c)
    toks = raw.split('\0')
    entries = []
    i = 0
    while i < len(toks):
        t = toks[i]
        if not t.startswith(':'):
            i += 1
            continue
        st = t.split()[-1]
        if st[0] in 'RC':
            entries.append([st[0], toks[i + 1], toks[i + 2]])
            i += 3
        else:
            entries.append([st[0], toks[i + 1], toks[i + 1]])
            i += 2
    ns = git('show', '--numstat', '-M', '-z', '--format=', c)
    toks = ns.split('\0')
    nums = {}
    i = 0
    while i < len(toks):
        t = toks[i].lstrip('\n')
        if not t:
            i += 1
            continue
        parts = t.split('\t')
        a, d = parts[0], parts[1]
        a = None if a == '-' else int(a)
        d = None if d == '-' else int(d)
        if len(parts) >= 3 and parts[2] != '':
            nums[parts[2]] = (a, d)
            i += 1
        else:
            old, new = toks[i + 1], toks[i + 2]
            nums[new] = (a, d)
            i += 3
    out = []
    for st, old, new in entries:
        a, d = nums.get(new, (0, 0))
        out.append((st, old, new, a, d))
    return out

def blob_size(rev, path):
    try:
        return int(git('cat-file', '-s', f'{rev}:{path}').strip())
    except subprocess.CalledProcessError:
        return None

def blob_lines(rev, path):
    try:
        b = git('show', f'{rev}:{path}', binary=True)
    except subprocess.CalledProcessError:
        return None
    return b.count(b'\n')

def main():
    spec = json.load(open(sys.argv[1]))
    commits = spec['commits']
    landing = spec['landing']
    base = spec['base']
    out = spec['out']
    per_file = collections.OrderedDict()  # final path -> info
    renames = []
    for c in commits:
        for st, old, new, a, d in commit_changes(c):
            key = new
            if st == 'R' and old in per_file:
                info = per_file.pop(old)
                info['renamed_from'].append(old)
            else:
                info = per_file.get(key) or {'first': None, 'statuses': [], 'add': 0, 'del': 0,
                                             'binary': False, 'renamed_from': [], 'commits': []}
            if info['first'] is None:
                info['first'] = st
                info['orig'] = old
            info['statuses'].append(st)
            info['commits'].append(c[:9])
            if a is None:
                info['binary'] = True
            else:
                info['add'] += a
                info['del'] += d
            if st == 'R':
                renames.append((c[:9], old, new, a, d))
            per_file[key] = info
    rows = []
    for p, info in per_file.items():
        cat = category(p)
        exists_landing = blob_size(landing, p)
        exists_base_orig = blob_size(base, info.get('orig', p))
        size_land = exists_landing if exists_landing is not None else 0
        size_base = exists_base_orig if exists_base_orig is not None else 0
        lines_land = blob_lines(landing, p) if exists_landing is not None else 0
        rows.append({
            'path': p, 'cat': cat, 'first': info['first'], 'statuses': ''.join(info['statuses']),
            'orig': info.get('orig', p), 'add': info['add'], 'del': info['del'], 'binary': info['binary'],
            'at_base': exists_base_orig is not None, 'at_landing': exists_landing is not None,
            'bytes_landing': size_land, 'bytes_base': size_base, 'lines_landing': lines_land,
            'commits': ','.join(info['commits']),
        })
    json.dump({'rows': rows, 'renames': renames}, open(out, 'w'), indent=1)
    print('files', len(rows))

if __name__ == '__main__':
    main()

